/* Microfix 3.8.59: the empty-canvas welcome follows every supported language immediately */
function syncEmptyHintLanguage(){
  const copy={
    en:{title:"Build the project with your AI team",text:"Files, code, websites, design and decisions live on one canvas. Attach agents to exact objects and keep the whole context visible."},
    ru:{title:"Соберите проект вместе с командой ИИ",text:"Файлы, код, сайты, дизайн и решения живут на одном холсте. Подключайте агентов к конкретным объектам — весь контекст всегда остаётся перед глазами."},
    de:{title:"Erstelle das Projekt mit deinem KI-Team",text:"Dateien, Code, Websites, Design und Entscheidungen leben auf einer gemeinsamen Arbeitsfläche. Verknüpfe Agenten mit konkreten Objekten und behalte den gesamten Kontext im Blick."},
    es:{title:"Construye el proyecto con tu equipo de IA",text:"Archivos, código, sitios web, diseño y decisiones conviven en un solo lienzo. Vincula agentes a objetos concretos y mantén siempre visible todo el contexto."},
    ja:{title:"AIチームと一緒にプロジェクトを構築",text:"ファイル、コード、Webサイト、デザイン、意思決定を1つのキャンバスにまとめます。エージェントを特定のオブジェクトに接続し、全体のコンテキストを常に見える状態に保ちます。"},
    zh:{title:"与 AI 团队一起构建项目",text:"文件、代码、网站、设计和决策都集中在同一画布上。将智能体连接到具体对象，并始终保持完整上下文可见。"}
  }[state.language]||null;
  const fallback={title:(COPY[state.language]||COPY.en).emptyTitle,text:(COPY[state.language]||COPY.en).emptyText};
  const value=copy||fallback,empty=document.getElementById("emptyHint");
  if(!empty)return;
  const title=empty.querySelector("h2"),body=empty.querySelector("p");
  if(title)title.textContent=value.title;if(body)body.textContent=value.text;
}
syncEmptyHintLanguage();
